  let path=OsStr::new(&runtime.root).encode_wide().chain(Some(0)).collect::<Vec<_>>();let owner=open(path.as_ptr(),luid);if owner==0{return Err(Self::message(error));}let mut bytes=[0;4096];let n=info(owner,bytes.as_mut_ptr(),bytes.len()as u32);if n as usize>bytes.len(){close(owner);return Err("E_NATIVE_OPTIX_ABI: invalid runtime metadata".into());}let runtime_info=match serde_json::from_slice(&bytes[..n as usize]){Ok(v)=>v,Err(e)=>{close(owner);return Err(format!("E_NATIVE_OPTIX_ABI: {e}"));}};
